#include "../primal_cubic_20261109_v6/frozen_lll_prefix.hpp"
#include <set>
#include <functional>
#include "../primal_cubic_20261109_v6/integer_cubic.hpp"
struct Enum{Mat basis;Vec weights,offset,hi;std::set<Vec>points;unsigned steps=0;uint64_t nodes=0,higher_nodes=0,leaf_proposals_visited=0;I leaf_interval_candidates=0,leaf_candidate_values=0,full_fallback_interval_candidates=0;unsigned quadratic_leaves=0,linear_leaves=0,full_leaves=0,empty_leaves=0;bool complete=true;};
struct PrimalLeaf{bool all=false;std::set<I> values;};
PrimalLeaf primal_leaf(const I&alpha,const I&beta,const I&s,const I&v,const I&lo,const I&hi){PrimalLeaf out;if(lo>hi)return out;I A=alpha*alpha,B=2*alpha*s-beta,C=s*s-v;auto put=[&](const I&z){if(lo<=z&&z<=hi)out.values.insert(z);};if(A!=0){I disc=B*B-4*A*C;if(disc<0)return out;I root;mpz_sqrt(root.get_mpz_t(),disc.get_mpz_t());if(root*root!=disc)return out;I den=2*A;for(I num:{I(-B-root),I(-B+root)})if(num%den==0)put(I(num/den));}else if(B!=0){I num=-C;if(num%B==0)put(I(num/B));}else if(C==0)out.all=true;return out;}
unsigned bits(const I&x){return mpz_sizeinbase(x.get_mpz_t(),2);}
Enum enumerate(const I&p,const I&M,const Quad&t,const Quad&u){Enum e;e.offset={0,0,t[2],u[2]};e.hi={I(3*M),I(9*M*M),I(3*M*M),I(M*M*M)};unsigned B=0;for(int j=0;j<4;j++)B=std::max(B,bits(I(e.hi[j]+1)));for(int j=0;j<4;j++){e.weights[j]=1;e.weights[j]<<=B-bits(I(e.hi[j]+1));}e.basis={Vec{1,0,t[1],u[1]},Vec{0,1,t[0],u[0]},Vec{0,0,p,0},Vec{0,0,0,p}};for(auto&row:e.basis)for(int j=0;j<4;j++)row[j]*=2*e.weights[j];lll(e.basis,e.steps);GS g=gram(e.basis);Vec C;Q radius=0;for(int j=0;j<4;j++){C[j]=e.weights[j]*(e.hi[j]-2*e.offset[j]);I z=e.weights[j]*e.hi[j];radius+=Q(z*z);}std::array<Q,4>target;for(int i=0;i<4;i++){Q dot=0;for(int j=0;j<4;j++)dot+=Q(C[j])*g.s[i][j];target[i]=dot/g.norm[i];}Vec coeff{};
std::function<void(int,Q)> rec=[&](int i,Q used){if(!e.complete)return;if(i<0){Vec x=e.offset;for(int j=0;j<4;j++){I v=0;for(int k=0;k<4;k++)v+=coeff[k]*e.basis[k][j];I den=2*e.weights[j];need(v%den==0,"exact lattice unscale");x[j]+=v/den;if(x[j]<0||x[j]>e.hi[j])return;}need(imod(x[2]-t[0]*x[1]-t[1]*x[0]-t[2],p)==0&&imod(x[3]-u[0]*x[1]-u[1]*x[0]-u[2],p)==0,"primal membership");need(x[1]==x[0]*x[0],"parabola leaf equality");e.points.insert(x);return;}Q remain=radius-used;if(remain<0)return;Q center=target[i];for(int j=i+1;j<4;j++)center-=Q(coeff[j])*g.mu[j][i];Q bound=remain/g.norm[i];I A=center.get_num(),D=center.get_den();Q square=Q(D*D)*bound;I q=fd(square.get_num(),square.get_den()),T;need(q>=0,"nonnegative square bound");mpz_sqrt(T.get_mpz_t(),q.get_mpz_t());I lo=cd(A-T,D),hi=fd(A+T,D);if(lo>hi)return;auto visit=[&](const I&z){if(e.nodes>=100000){e.complete=false;return;}e.nodes++;if(i==0)e.leaf_proposals_visited++;else e.higher_nodes++;coeff[i]=z;Q delta=Q(z)-center;rec(i-1,used+g.norm[i]*delta*delta);};if(i==0){I sv[2];for(int j=0;j<2;j++){I den=2*e.weights[j],vv=0;for(int k=1;k<4;k++)vv+=coeff[k]*e.basis[k][j];need(vv%den==0&&e.basis[0][j]%den==0,"integral parabola coefficients");sv[j]=e.offset[j]+vv/den;}I alpha=e.basis[0][0]/(2*e.weights[0]),beta=e.basis[0][1]/(2*e.weights[1]);PrimalLeaf leaf=primal_leaf(alpha,beta,sv[0],sv[1],lo,hi);I width=hi-lo+1;e.leaf_interval_candidates+=width;if(alpha!=0)e.quadratic_leaves++;else if(beta!=0)e.linear_leaves++;else if(leaf.all){e.full_leaves++;e.full_fallback_interval_candidates+=width;}else e.empty_leaves++;e.leaf_candidate_values+=leaf.all?width:I(leaf.values.size());if(leaf.all){for(I z=lo;z<=hi;z++){visit(z);if(!e.complete)return;}}else{for(const I&z:leaf.values){visit(z);if(!e.complete)return;}}}else{for(I z=lo;z<=hi;z++){visit(z);if(!e.complete)return;}}};rec(3,Q(0));return e;}
using Sol=std::array<I,4>;
std::set<Sol> recover(const Enum&e,const I&M,unsigned&unresolved){std::set<Sol>out;unresolved=0;for(const auto&x:e.points){need(x[1]==x[0]*x[0],"curved point before cubic isolation");auto cubic=primal_cubic_support(x[0],x[2],x[3],M);if(!cubic.supported)continue;auto roots=cubic.roots;do{out.insert({x[0],roots[0],roots[1],roots[2]});}while(std::next_permutation(roots.begin(),roots.end()));}return out;}
void vec(std::ostream&o,const Vec&v){o<<'[';for(int j=0;j<4;j++){if(j)o<<',';o<<'"'<<v[j]<<'"';}o<<']';}
void primal_controls(){uint64_t leaf_checks=0;for(long alpha=-2;alpha<=2;alpha++)for(long beta=-2;beta<=2;beta++)for(long ss=-2;ss<=2;ss++)for(long vv=-2;vv<=2;vv++){auto leaf=primal_leaf(I(alpha),I(beta),I(ss),I(vv),I(-3),I(3));for(long z=-3;z<=3;z++){bool truth=(ss+alpha*z)*(ss+alpha*z)==vv+beta*z;need(truth==(leaf.all||leaf.values.count(I(z))!=0),"independent leaf integer oracle");leaf_checks++;}}std::cerr<<"leaf_integer_checks="<<leaf_checks<<'\n';uint64_t count=0,tuples=0;for(long p:{5L,7L,11L})for(long M:{1L,2L})for(long k=0;k<2;k++){Quad t{I(k),I((k+1)%p),I(k)},u{I((k+1)%p),I(k),I(k)};Enum e=enumerate(I(p),I(M),t,u);need(e.complete,"tiny enumeration complete");std::set<Vec>truth;for(long S=0;S<=3*M;S++)for(long V=0;V<=9*M*M;V++)for(long T=0;T<=3*M*M;T++)for(long U=0;U<=M*M*M;U++){tuples++;auto md=[&](long z){z%=p;return z<0?z+p:z;};if(V==S*S&&md(T-t[0].get_si()*V-t[1].get_si()*S-t[2].get_si())==0&&md(U-u[0].get_si()*V-u[1].get_si()*S-u[2].get_si())==0)truth.insert({I(S),I(V),I(T),I(U)});}need(e.points==truth,"independent brute-force curved-box set");unsigned unknown=0;auto sols=recover(e,I(M),unknown);need(!unknown,"tiny roots complete");std::set<Sol>oracle;for(long x=0;x<=M;x++)for(long y=0;y<=M;y++)for(long z=0;z<=M;z++){long S=x+y+z,T=x*y+x*z+y*z,U=x*y*z;auto md=[&](long v){v%=p;return v<0?v+p:v;};if(md(T-t[0].get_si()*S*S-t[1].get_si()*S-t[2].get_si())==0&&md(U-u[0].get_si()*S*S-u[1].get_si()*S-u[2].get_si())==0)oracle.insert({I(S),I(x),I(y),I(z)});}need(sols==oracle,"independent ordered-root multiset oracle");count++;}std::cerr<<"tiny_cases="<<count<<" brute_tuples="<<tuples<<'\n';}
